val nud: Map<KClass<out Token>, (Parser, Token) -> Expr> = mapOf(
    Literal::class to { _, t -> Expr.Lit((t as Literal).value) },
    Minus::class   to { p, _ -> Expr.Neg(p.expr(70)) },        // prefix binding power
)
fun expr(minBp: Int): Expr {
    var left = nud.getValue(peek()::class)(this, next())       // null denotation
    while (minBp < peek().bindingPower) {                      // left denotation
        val op = next()
        left = led.getValue(op::class)(this, left, op)
    }
    return left
}
